请对以下 case 进行三维加权评分。

=== case_id ===
Case-30-pet-feeder-019

=== 用户原始指令 (query.txt) ===
极简风喂食卡,我之前做的一版按钮太多太乱,这次想要左边一个圆形进度环,右边"余粮32%"动态数字+固定文字,底下横向排三四个信息块(今日喂了几次、最近出粮时间、宠物状态)。点最右边的"播放音乐"能跳歌单。字符图标,别加渐变,余粮低于20%要有提醒状态。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "极简风喂食卡,我之前做的一版按钮太多太乱,这次想要左边一个圆形进度环,右边\"余粮32%\"动态数字+固定文字,底下横向排三四个信息块(今日喂了几次、最近出粮时间、宠物状态)。点最右边的\"播放音乐\"能跳歌单。字符图标,别加渐变,余粮低于20%要有提醒状态。",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hwmusic://com.huawei.hmsapp.music/showMusicList?code=a001&type=4"
      }
    }
  ],
  "dataModelSchema": {
    "feeder": {
      "grainPercent": {
        "type": "number",
        "description": "当前余粮百分比数值，用于圆形进度环。",
        "sampleValue": 32
      },
      "grainPercentText": {
        "type": "string",
        "description": "当前余粮百分比展示文本。",
        "sampleValue": "32%"
      },
      "progressTotal": {
        "type": "number",
        "description": "余粮进度环总量基准。",
        "sampleValue": 100
      },
      "ringColor": {
        "type": "string",
        "description": "余粮进度环颜色，余粮低于20%时切换为提醒色。",
        "sampleValue": "#ff0a59f7"
      },
      "statusLabel": {
        "type": "string",
        "description": "余粮状态文案，余粮低于20%时显示提醒状态。",
        "sampleValue": "正常"
      },
      "statusColor": {
        "type": "string",
        "description": "余粮状态文字颜色，低余粮时使用提醒色。",
        "sampleValue": "#99000000"
      },
      "warningHint": {
        "type": "string",
        "description": "低余粮提醒阈值提示文案。",
        "sampleValue": "20%提醒"
      }
    },
    "stats": {
      "todayFeedsText": {
        "type": "string",
        "description": "今日已喂食次数展示文本。",
        "sampleValue": "3次"
      },
      "recentDispenseTime": {
        "type": "string",
        "description": "最近一次出粮时间展示文本。",
        "sampleValue": "8:20"
      },
      "petStatusShort": {
        "type": "string",
        "description": "宠物当前状态短文本。",
        "sampleValue": "好"
      }
    },
    "action": {
      "musicLabel": {
        "type": "string",
        "description": "跳转歌单动作展示文案。",
        "sampleValue": "播放音乐"
      }
    }
  },
  "assetCandidates": []
}

